// 1-bit proportional bitmap fonts (generated by tools/make_font.py).
#pragma once

#include <stdint.h>

typedef struct {
    uint32_t cp;      // Unicode code point
    uint32_t offset;  // byte offset of this glyph's rows in font_t.bitmap
    uint8_t w, h;     // bitmap size in pixels
    int8_t xoff;      // left edge relative to the pen position
    int8_t yoff;      // top edge relative to the baseline (negative = above)
    uint8_t adv;      // how far the pen moves after this glyph
} glyph_t;

typedef struct {
    const uint8_t *bitmap;  // rows packed MSB-first, each row padded to whole bytes
    const glyph_t *glyphs;  // sorted by code point
    uint16_t count;
    uint8_t line_height;
    uint8_t ascent;  // pixels above the baseline
} font_t;

// Returns the glyph for `cp`, or NULL if the font doesn't have it.
const glyph_t *font_glyph(const font_t *f, uint32_t cp);

// The two fonts the face uses.
extern const font_t font_caption;  // subtitles
extern const font_t font_small;    // status strips
